selector_to_html = {"a[href=\"basic-usage.html#transfer-data-between-devices\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Transfer data between devices<a class=\"headerlink\" href=\"#transfer-data-between-devices\" title=\"Link to this heading\">#</a></h2>", "a[href=\"operator-dispatch-guide.html#runtime-environment-variables\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Runtime environment variables<a class=\"headerlink\" href=\"#runtime-environment-variables\" title=\"Link to this heading\">#</a></h2>", "a[href=\"testing.html#pytest-marks\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Pytest marks<a class=\"headerlink\" href=\"#pytest-marks\" title=\"Link to this heading\">#</a></h2><p>Use <code class=\"docutils literal notranslate\"><span class=\"pre\">-m</span> <span class=\"pre\">&lt;mark&gt;</span></code> to run specific test categories. Example: <code class=\"docutils literal notranslate\"><span class=\"pre\">pytest</span> <span class=\"pre\">tests/integration/ops/</span> <span class=\"pre\">-m</span> <span class=\"pre\">cuda</span></code> runs only CUDA tests.</p>", "a[href=\"operator-dispatch-guide.html#dispatch-through-environment-variables\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Dispatch through environment variables<a class=\"headerlink\" href=\"#dispatch-through-environment-variables\" title=\"Link to this heading\">#</a></h2><p>Individual operators can be overridden via environment variables (higher priority than config file):</p>", "a[href=\"query-device-and-ops.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Query device and operator information<a class=\"headerlink\" href=\"#query-device-and-operator-information\" title=\"Link to this heading\">#</a></h1>", "a[href=\"testing.html#ascend-platform\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Ascend platform<a class=\"headerlink\" href=\"#ascend-platform\" title=\"Link to this heading\">#</a></h2>", "a[href=\"basic-usage.html#manage-device-context\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Manage device context<a class=\"headerlink\" href=\"#manage-device-context\" title=\"Link to this heading\">#</a></h2>", "a[href=\"operator-dispatch-guide.html#debug-dispatch\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Debug Dispatch<a class=\"headerlink\" href=\"#debug-dispatch\" title=\"Link to this heading\">#</a></h2>", "a[href=\"basic-usage.html#import-and-register-device\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Import and register device<a class=\"headerlink\" href=\"#import-and-register-device\" title=\"Link to this heading\">#</a></h2>", "a[href=\"operator-dispatch-guide.html#c-stub-only-mode\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">C++ stub-only mode<a class=\"headerlink\" href=\"#c-stub-only-mode\" title=\"Link to this heading\">#</a></h2><p>You can disable the FlagGems Python-layer registration entirely, leaving only the C++ unified wrapper active. This is useful for verifying that all required operators are covered by C++ stubs.</p>", "a[href=\"testing.html#cuda-platform\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">CUDA platform<a class=\"headerlink\" href=\"#cuda-platform\" title=\"Link to this heading\">#</a></h2>", "a[href=\"operator-dispatch-guide.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Operator dispatch user guide<a class=\"headerlink\" href=\"#operator-dispatch-user-guide\" title=\"Link to this heading\">#</a></h1><p>You can configure whether to use FlagGems or native vendor backend at per-operator granularity. Dispatching operators through environment variables takes higher priority than dispatching through configuration file.</p>", "a[href=\"#user-guide\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">User Guide<a class=\"headerlink\" href=\"#user-guide\" title=\"Link to this heading\">#</a></h1><p>This guide covers the usage of PyTorch-Plugin-FL, including basic operations, device management, backend configuration, and debugging.</p>", "a[href=\"testing.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Run tests<a class=\"headerlink\" href=\"#run-tests\" title=\"Link to this heading\">#</a></h1><p>Tests in <code class=\"docutils literal notranslate\"><span class=\"pre\">tests/integration/ops/</span></code> are marked with <code class=\"docutils literal notranslate\"><span class=\"pre\">@pytest.mark</span></code> to indicate platform scope.</p>", "a[href=\"operator-dispatch-guide.html#dispatch-through-configuration-file\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Dispatch through configuration file<a class=\"headerlink\" href=\"#dispatch-through-configuration-file\" title=\"Link to this heading\">#</a></h2><p>Default path is <code class=\"docutils literal notranslate\"><span class=\"pre\">torch_fl/backends.conf</span></code>, can be overridden via the <code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGOS_BACKEND_CONFIG</span></code> environment variable.</p>", "a[href=\"basic-usage.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Basic Usage<a class=\"headerlink\" href=\"#basic-usage\" title=\"Link to this heading\">#</a></h1><h2>Import and register device<a class=\"headerlink\" href=\"#import-and-register-device\" title=\"Link to this heading\">#</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
